CREATE OR REPLACE FUNCTION public.ec_can_storage_object(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
declare
  v_org text := split_part(p_name, '/', 1);
  v_scope text := split_part(p_name, '/', 2);
  v_doc_id text := nullif(split_part(p_name, '/', 3), '');
  v_doc_data jsonb;
begin
  if v_org <> current_org()::text then return false; end if;

  if v_doc_id is not null then
    select d.data into v_doc_data
      from ec_docs d
      where d.org_id = current_org() and d.id = v_doc_id
      limit 1;
  end if;

  if v_doc_data is null then
    select d.data into v_doc_data
      from ec_docs d
      where d.org_id = current_org() and d.id = v_scope
      limit 1;
  end if;

  if v_doc_data is not null then
    return ec_can_document(v_doc_data);
  end if;

  -- Durante una carga nueva el objeto se crea antes que su ficha ec_docs.
  -- La inserción posterior de la ficha vuelve a validar tipo y facturación.
  if exists (select 1 from ec_studies s where s.org_id = current_org() and s.id = v_scope) then
    return ec_can_study(v_scope);
  end if;
  return false;
end $function$

CREATE OR REPLACE FUNCTION public.ec_members_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  /* sin sesion de usuario = acceso directo por SQL Editor o service_role:
     es el dueno del proyecto o la Edge Function, no se restringe */
  if auth.uid() is null then return new; end if;
  if es_superadmin() then return new; end if;

  if tg_op = 'INSERT' and new.superadmin then
    raise exception 'Solo un superadministrador puede otorgar ese permiso';
  end if;

  if tg_op = 'UPDATE' then
    if new.superadmin is distinct from old.superadmin then
      raise exception 'Solo un superadministrador puede otorgar ese permiso';
    end if;
    if new.org_id is distinct from old.org_id then
      raise exception 'No se puede mover un usuario a otra organizacion';
    end if;
    if new.user_id = auth.uid() and new.rol is distinct from old.rol then
      raise exception 'No podes cambiar tu propio rol';
    end if;
  end if;

  return new;
end $function$
